service.method:

SELECT SMR_NUMBER
  FROM SSETL
 WHERE APVID = ${APPR_DOC_NO}


UPDATE SSIAD
   SET SMR_STATUS = 'I'
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


UPDATE SSETL
   SET SMR_STATUS = 'I'
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


		UPDATE SSIAD
		   SET SMR_STATUS = ${SMR_STATUS}
  		     , REJECT_REASON = ${APPR_COMMENT}
  		     , CONFIRM_USER_ID = ${APPR_USER_ID}
  		     , CONFIRM_DATE = ${ACCEPT_DATE}
  		     , CONFIRM_TIME = ${ACCEPT_TIME}
		 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
		   AND COMPANY_CODE = ${session.COMPANY_CODE}
		   AND SMR_NUMBER 	= ${SMR_NUMBER}


		UPDATE SSETL
		   SET SMR_STATUS = ${SMR_STATUS}
  		     , REJECT_REMARK = ${APPR_COMMENT}
  		     , CONFIRM_USER_ID = ${APPR_USER_ID}
  		     , CONFIRM_DATE = ${ACCEPT_DATE}
  		     , CONFIRM_TIME = ${ACCEPT_TIME}
		 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
		   AND COMPANY_CODE = ${session.COMPANY_CODE}
		   AND SMR_NUMBER 	= ${SMR_NUMBER}


SELECT CONCAT(APPLY_TYPE, 'S') AS APPLY_FOR
     , RE_FLAG
  FROM SSIAD
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


SELECT CONCAT(APPLY_TYPE, 'S') AS APPLY_FOR
  FROM SSETL
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


INSERT INTO SAPPP (
       HOUSE_CODE
     , COMPANY_CODE
     , SMR_NUMBER
     , SEQ
     , RECENT
     , APP_STATUS
     , APPLY_FOR
     , POSTPROCESSED
     , ADD_DATE
     , ADD_TIME
     , CONFIRM_USER_ID
     , APP_COMMENT
     , APP_NO
     , APP_NO_SEQ
     , APP_LINE_SEQ
     , RE_FLAG
) VALUES(
       ${session.HOUSE_CODE}
     , ${session.COMPANY_CODE}
     , ${SMR_NUMBER}
     , CAST((CAST(NVL(
     			(SELECT PP.SEQ
				  FROM SAPPP PP
		 		 WHERE PP.HOUSE_CODE = ${session.HOUSE_CODE}
		   		   AND PP.COMPANY_CODE = ${session.COMPANY_CODE}
		   		   AND PP.SMR_NUMBER = ${SMR_NUMBER})
       , '0') as unsigned) + 1) as char)
     , 'Y'
     , ${SMR_STATUS}
     , ${APPLY_FOR}
     , 'N'
     , ${ACCEPT_DATE}
     , ${ACCEPT_TIME}
     , ${APPR_USER_ID}
     , ${APPR_COMMENT}
     , ${APP_NO}
     , ${APP_NO_SEQ}
     , ${APP_LINE_SEQ}
     , ${RE_FLAG}
)


UPDATE SSEDC_SEAL SET
	COMPLETE_FLAG	= ${COMPLETE_FLAG}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}
